   251→// SimulateHeartbeat is used in tests to manually trigger heartbeat processing.
   252→func (c *Cluster) SimulateHeartbeat(nodeID string, alive bool) {
   253→	c.mu.Lock()
   254→	defer c.mu.Unlock()
   255→
   256→	node, ok := c.nodes[nodeID]
   257→	if !ok {
   258→		return
   259→	}
   260→
   261→	if alive {
   262→		node.RecordHeartbeat()
   263→		node.MarkAlive()
   264→	} else {
   265→		// Simulate missed heartbeats by setting lastHeartbeat far in the past.
   266→		node.mu.Lock()
   267→		node.lastHeartbeat = time.Now().Add(-10 * DefaultHeartbeatInterval)
   268→		node.mu.Unlock()
   269→		node.MarkDead()
   270→	}
   271→}
   272→
   273→// StartHeartbeat begins background goroutine for periodic heartbeat monitoring.
   274→func (c *Cluster) StartHeartbeat(interval time.Duration) {
   275→	c.ticker = time.NewTicker(interval)
   276→	go func() {
   277→		defer close(c.done)
   278→		for {
   279→			select {
   280→			case <-c.ticker.C:
   281→				c.processHeartbeat(interval)
   282→			case <-c.stopCh:
   283→				c.ticker.Stop()
   284→				return
   285→			}
   286→		}
   287→	}()
   288→}
   289→
   290→// processHeartbeat checks the health of all nodes and transitions states as needed.
   291→func (c *Cluster) processHeartbeat(interval time.Duration) {
   292→	c.mu.RLock()
   293→	nodes := make([]*Node, 0, len(c.nodes))
   294→	for _, node := range c.nodes {
   295→		nodes = append(nodes, node)
   296→	}
   297→	c.mu.RUnlock()
   298→
   299→	for _, node := range nodes {
   300→		age := node.HeartbeatAge()
   301→		beatThreshold := time.Duration(HeartbeatMissThreshold) * interval
   302→
   303→		if age < interval {
   304→			// Recent heartbeat, ensure Alive.
   305→			if !node.IsAlive() {
   306→				node.MarkAlive()
   307→			}
   308→		} else if age < beatThreshold {
   309→			// Missed one but not all, mark Suspect.
   310→			if node.Status == NodeAlive {
   311→				node.MarkSuspect()
   312→			}
   313→		} else {
   314→			// Missed too many, mark Dead.
   315→			node.mu.RLock()
   316→			currentStatus := node.Status
   317→			node.mu.RUnlock()
   318→
   319→			if currentStatus != NodeDead {
   320→				node.MarkDead()
   321→			}
   322→		}
   323→	}
   324→}
   325→
   326→// StopHeartbeat shuts down the heartbeat goroutine gracefully.
   327→func (c *Cluster) StopHeartbeat() {
   328→	if c.ticker != nil {
   329→		close(c.stopCh)
   330→		<-c.done
   331→	}
   332→}
   333→
   334→// Errors returns non-fatal accumulated errors.
   335→func (c *Cluster) Errors() []string {
   336→	c.mu.RLock()
   337→	defer c.mu.RUnlock()
   338→	return append([]string(nil), c.errors...)
   339→}
   340→
   341→// Stats returns a snapshot of cluster health.
   342→func (c *Cluster) Stats() ClusterStats {
   343→	c.mu.RLock()
   344→	defer c.mu.RUnlock()
   345→
   346→	alive := 0
   347→	dead := 0
   348→	for _, node := range c.nodes {
   349→		if node.IsAlive() {
   350→			alive++
   351→		} else {
   352→			dead++
   353→		}
   354→	}
   355→
   356→	totalKeys := 0
   357→	for _, s := range c.stores {
   358→		totalKeys += s.size()
   359→	}
   360→
   361→	return ClusterStats{
   362→		TotalNodes: len(c.nodes),
   363→		AliveNodes: alive,
   364→		DeadNodes:  dead,
   365→		TotalKeys:  totalKeys,
   366→	}
   367→}
