     3→import (
     4→	"crypto/sha256"
     5→	"encoding/binary"
     6→	"fmt"
     7→	"sort"
     8→	"sync"
     9→)
    10→
    11→const DefaultVirtualNodes = 150
    12→
    13→// ringEntry represents one virtual node slot on the consistent hash ring.
    14→type ringEntry struct {
    15→	hash   uint32
    16→	nodeID string
    17→}
    18→
    19→// Ring implements consistent hashing over a sorted slice of ringEntries.
    20→type Ring struct {
    21→	entries      []ringEntry
    22→	nodeSet      map[string]bool
    23→	virtualNodes int
    24→	mu           sync.RWMutex
    25→}
    26→
    27→// NewRing creates a new Ring with the specified number of virtual nodes per physical node.
    28→func NewRing(virtualNodes int) *Ring {
    29→	return &Ring{
    30→		entries:      make([]ringEntry, 0, 256),
    31→		nodeSet:      make(map[string]bool),
    32→		virtualNodes: virtualNodes,
    33→	}
    34→}
    35→
    36→// Add places a node onto the ring by inserting virtualNodes entries.
    37→// It is idempotent: adding the same nodeID twice is a no-op.
    38→func (r *Ring) Add(nodeID string) {
    39→	r.mu.Lock()
    40→	defer r.mu.Unlock()
    41→
    42→	if r.nodeSet[nodeID] {
    43→		return // already present
    44→	}
    45→	r.nodeSet[nodeID] = true
    46→
    47→	// Insert virtualNodes entries for this physical node.
    48→	for i := 0; i < r.virtualNodes; i++ {
    49→		label := fmt.Sprintf("%s#%d", nodeID, i)
    50→		hash := r.hash(label)
    51→		r.entries = append(r.entries, ringEntry{hash: hash, nodeID: nodeID})
    52→	}
    53→
    54→	// Keep entries sorted by hash.
    55→	sort.Slice(r.entries, func(i, j int) bool {
    56→		return r.entries[i].hash < r.entries[j].hash
    57→	})
    58→}
    59→
    60→// Remove deletes all virtual nodes for nodeID from the ring.
    61→func (r *Ring) Remove(nodeID string) {
    62→	r.mu.Lock()
    63→	defer r.mu.Unlock()
    64→
    65→	if !r.nodeSet[nodeID] {
    66→		return // not present
    67→	}
    68→	delete(r.nodeSet, nodeID)
    69→
    70→	// Filter out all entries belonging to this nodeID.
    71→	filtered := make([]ringEntry, 0, len(r.entries))
    72→	for _, entry := range r.entries {
    73→		if entry.nodeID != nodeID {
    74→			filtered = append(filtered, entry)
    75→		}
    76→	}
    77→	r.entries = filtered
    78→}
    79→
    80→// GetN returns up to n distinct physical node IDs starting from the successor
    81→// of hash(key). Used to select primary + replicas.
    82→// Returns ErrNoAliveNodes if the ring is empty.
    83→func (r *Ring) GetN(key string, n int) ([]string, error) {
    84→	r.mu.RLock()
    85→	defer r.mu.RUnlock()
    86→
    87→	if len(r.entries) == 0 {
    88→		return nil, ErrNoAliveNodes
    89→	}
    90→
    91→	keyHash := r.hash(key)
    92→
    93→	// Binary search to find the first entry >= keyHash.
    94→	pos := sort.Search(len(r.entries), func(i int) bool {
    95→		return r.entries[i].hash >= keyHash
    96→	})
    97→
    98→	if pos == len(r.entries) {
    99→		pos = 0 // wrap around to the beginning
   100→	}
   101→
   102→	// Collect up to n distinct physical node IDs.
   103→	result := make([]string, 0, n)
   104→	seen := make(map[string]bool)
   105→	for i := 0; i < len(r.entries) && len(result) < n; i++ {
   106→		idx := (pos + i) % len(r.entries)
   107→		nodeID := r.entries[idx].nodeID
   108→		if !seen[nodeID] {
   109→			seen[nodeID] = true
   110→			result = append(result, nodeID)
   111→		}
   112→	}
   113→
   114→	return result, nil
   115→}
   116→
   117→// Get returns the primary node for key (convenience wrapper for GetN(key, 1)).
   118→func (r *Ring) Get(key string) (string, error) {
   119→	nodes, err := r.GetN(key, 1)
   120→	if err != nil {
   121→		return "", err
   122→	}
   123→	if len(nodes) == 0 {
   124→		return "", ErrNoAliveNodes
   125→	}
   126→	return nodes[0], nil
   127→}
   128→
   129→// Nodes returns a deduplicated list of all physical node IDs in the ring.
   130→func (r *Ring) Nodes() []string {
   131→	r.mu.RLock()
   132→	defer r.mu.RUnlock()
   133→
   134→	result := make([]string, 0, len(r.nodeSet))
   135→	for nodeID := range r.nodeSet {
   136→		result = append(result, nodeID)
   137→	}
   138→	return result
   139→}
   140→
   141→// hash computes a deterministic uint32 from a string using SHA-256,
   142→// then truncates to the first 4 bytes (big-endian).
   143→func (r *Ring) hash(data string) uint32 {
   144→	sum := sha256.Sum256([]byte(data))
   145→	return binary.BigEndian.Uint32(sum[:4])
   146→}
