    16→// ============ Ring Tests ============
    17→
    18→func TestRingAdd(t *testing.T) {
    19→	r := NewRing(10)
    20→	r.Add("node-1")
    21→
    22→	nodes := r.Nodes()
    23→	if len(nodes) != 1 || nodes[0] != "node-1" {
    24→		t.Errorf("Expected [node-1], got %v", nodes)
    25→	}
    26→}
