    28→func TestRingAddIdempotent(t *testing.T) {
    29→	r := NewRing(10)
    30→	r.Add("node-1")
    31→	r.Add("node-1") // second add should be no-op
    32→
    33→	nodes := r.Nodes()
    34→	if len(nodes) != 1 {
    35→		t.Errorf("Expected 1 node, got %d", len(nodes))
    36→	}
    37→}
