   117→func TestRingDistribution(t *testing.T) {
   118→	r := NewRing(150)
   119→	r.Add("A")
   120→	r.Add("B")
   121→	r.Add("C")
   122→	r.Add("D")
   123→	r.Add("E")
   124→
   125→	counts := make(map[string]int)
   126→	for i := 0; i < 10000; i++ {
   127→		key := "key-" + string(rune(i))
   128→		primary, _ := r.Get(key)
   129→		counts[primary]++
   130→	}
   131→
   132→	// With 5 nodes and 10000 keys, expect each to have ~2000 keys.
   133→	// Allow 30% variance.
   134→	expectedPerNode := 10000 / 5
   135→	maxVariance := int(float64(expectedPerNode) * 0.3)
   136→
   137→	for node, count := range counts {
   138→		if count < expectedPerNode-maxVariance || count > expectedPerNode+maxVariance {
   139→			t.Errorf("Node %s has %d keys (expected ~%d, variance %d)", node, count, expectedPerNode, maxVariance)
   140→		}
   141→	}
   142→}
